arguments.file_text:
@using sv_035ca291cf844edaa72b58e39729e95c.Services
@inject ISettingsService SettingsService

<h4>Profile</h4>
<hr />

@if (_loading)
{
    <p>Loading profile…</p>
}
else
{
    <div class="profile-grid">
        <div class="profile-fields">
            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_displayName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_bio"></textarea>
            </div>
        </div>

        <div class="avatar-area">
            <label class="form-label">Avatar Preview</label>
            <div class="avatar-preview">
                <img src="@_avatarUrl" alt="Avatar" />
            </div>
            <div class="mt-2">
                <small class="text-muted text-break">@_avatarUrl</small>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>

    @if (_showSuccess)
    {
        <div class="alert alert-success mt-3 fade-in" role="alert">
            ✅ Profile saved successfully!
        </div>
    }
}

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    private UserProfile _savedProfile = default!;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _bio = p.Bio;
        _avatarUrl = p.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _showSuccess = true;
        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        ApplyProfile(_savedProfile);
        _showSuccess = false;
    }
}

.profile-grid {
    display: grid;
    grid-template-columns: 1fr 200px;
