@code {
    private bool _loading = true;
    private bool _showSuccess;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        await SettingsService.SaveAppearanceAsync(
            new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _showSuccess = true;
        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private string PreviewStyle
    {
        get
        {
            var bg = _theme == "Dark" ? "#1e1e1e" : "#ffffff";
            var fg = _theme == "Dark" ? "#e0e0e0" : "#212529";
            var border = _theme == "Dark" ? "#444" : "#dee2e6";
            var size = _fontSize switch
            {
                "Small" => "0.85rem",
                "Large" => "1.15rem",
                _ => "1rem"
            };
            var padding = _compactMode ? "0.75rem" : "1.25rem";

            return $"background:{bg}; color:{fg}; border:1px solid {border}; " +
                   $"border-radius:8px; padding:{padding}; font-size:{size}; " +
                   $"transition: all 0.2s ease;";
        }
    }

    private string PreviewButtonClass => _theme == "Dark" ? "btn-outline-light" : "btn-outline-primary";
    private string PreviewBadgeClass => _theme == "Dark" ? "bg-light text-dark" : "bg-primary";
}
