@using sv_035ca291cf844edaa72b58e39729e95c.Services
@inject ISettingsService SettingsService

<h4>Appearance</h4>
<hr />

@if (_loading)
{
    <p>Loading appearance settings…</p>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <!-- Theme -->
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in _themes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="theme-@theme">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in _fontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="fs-@size">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h6>Language</h6>
                <select class="form-select" style="max-width: 220px;" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3" role="alert">
                    ✅ Appearance settings saved!
                </div>
            }
        </div>

        <!-- Live Preview -->
        <div class="col-md-6">
            <h6>Live Preview</h6>
            <div class="preview-box" style="@PreviewStyle">
                <h5 style="margin-top: 0;">Dashboard</h5>
                <p>This is a preview of your selected appearance settings.</p>
                <button class="btn @PreviewButtonClass btn-sm">Sample Button</button>
                <div class="mt-2">
                    <span class="badge @PreviewBadgeClass">Status</span>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        await SettingsService.SaveAppearanceAsync(
            new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _showSuccess = true;
        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private string PreviewStyle
    {
        get
        {
            var bg = _theme == "Dark" ? "#1e1e1e" : "#ffffff";
            var fg = _theme == "Dark" ? "#e0e0e0" : "#212529";
            var border = _theme == "Dark" ? "#444" : "#dee2e6";
            var size = _fontSize switch
            {
                "Small" => "0.85rem",
                "Large" => "1.15rem",
                _ => "1rem"
            };
            var padding = _compactMode ? "0.75rem" : "1.25rem";

            return $"background:{bg}; color:{fg}; border:1px solid {border}; " +
                   $"border-radius:8px; padding:{padding}; font-size:{size}; " +
                   $"transition: all 0.2s ease;";
        }
    }

    private string PreviewButtonClass => _theme == "Dark" ? "btn-outline-light" : "btn-outline-primary";
    private string PreviewBadgeClass => _theme == "Dark" ? "bg-light text-dark" : "bg-primary";
}

